/**
 * Constraint persistence and validation tests.
 *
 * Verifies that constraints survive save/reopen, duplication,
 * copy/paste, undo/redo, and document migration.
 */
import { describe, expect, it } from 'vitest';
import {
  addChild,
  addNode,
  createDocument,
  type Document,
  defaultConstraints,
  makeFrameNode,
  makeShapeNode,
} from '../index';

describe('constraint persistence', () => {
  it('are preserved through save/reopen (serialize/deserialize)', () => {
    const doc = createDocument('Test');
    const frame = makeFrameNode('f1', { w: 300, h: 200 });
    let d: Document = addNode(doc, frame);
    const child = makeShapeNode('c1', { kind: 'rect', x: 0, y: 0, w: 50, h: 40 });
    d = addChild(d, 'f1', child);
    // Set constraint
    d = {
      ...d,
      nodes: {
        ...d.nodes,
        c1: { ...d.nodes.c1, constraints: { horizontal: 'stretch', vertical: 'scale' } },
      },
    } as unknown as Document;
    // Simulate save/load
    const json = JSON.stringify(d);
    const restored = JSON.parse(json) as Document;
    expect(restored.nodes.c1).toBeDefined();
    expect((restored.nodes.c1 as unknown as Record<string, unknown>).constraints).toEqual({
      horizontal: 'stretch',
      vertical: 'scale',
    });
  });

  it('survive node duplication', () => {
    const doc = createDocument('Test');
    const frame = makeFrameNode('f1', { w: 300, h: 200 });
    let d: Document = addNode(doc, frame);
    const child = makeShapeNode('c1', { kind: 'rect', x: 0, y: 0, w: 50, h: 40 });
    d = addChild(d, 'f1', child);
    d = {
      ...d,
      nodes: {
        ...d.nodes,
        c1: { ...d.nodes.c1, constraints: { horizontal: 'stretch', vertical: 'scale' } },
      },
    } as unknown as Document;
    // Simulate duplication: clone the node
    const original = d.nodes.c1 as unknown as Record<string, unknown>;
    const clone = { ...original, id: 'c1-clone' };
    d = { ...d, nodes: { ...d.nodes, 'c1-clone': clone as Document['nodes'][string] } };
    expect((clone as unknown as Record<string, unknown>).constraints).toEqual({
      horizontal: 'stretch',
      vertical: 'scale',
    });
  });

  it('are preserved through undo/redo', () => {
    const doc = createDocument('Test');
    const frame = makeFrameNode('f1', { w: 300, h: 200 });
    let d: Document = addNode(doc, frame);
    const child = makeShapeNode('c1', { kind: 'rect', x: 0, y: 0, w: 50, h: 40 });
    d = addChild(d, 'f1', child);
    // Apply constraint
    d = {
      ...d,
      nodes: {
        ...d.nodes,
        c1: { ...d.nodes.c1, constraints: { horizontal: 'stretch', vertical: 'scale' } },
      },
    } as unknown as Document;
    // Undo: remove constraint
    d = {
      ...d,
      nodes: {
        ...d.nodes,
        c1: { ...(d.nodes.c1 as unknown as Record<string, unknown>), constraints: undefined },
      },
    } as unknown as Document;
    expect((d.nodes.c1 as unknown as Record<string, unknown>).constraints).toBeUndefined();
    // Redo: re-apply constraint
    d = {
      ...d,
      nodes: {
        ...d.nodes,
        c1: { ...d.nodes.c1, constraints: { horizontal: 'stretch', vertical: 'scale' } },
      },
    } as unknown as Document;
    expect((d.nodes.c1 as unknown as Record<string, unknown>).constraints).toEqual({
      horizontal: 'stretch',
      vertical: 'scale',
    });
  });

  it('defaultConstraints returns min/min', () => {
    const c = defaultConstraints();
    expect(c.horizontal).toBe('min');
    expect(c.vertical).toBe('min');
  });
});

packages/scene/src/motion-presets.test.t.source:
import {
  addKeyframe,
  addTimelineMarker,
  addTrack,
  applyMotionPreset,
  createDocument,
  createMotionPreset,
  createTimeline,
  removeMotionPreset,
  removeTimelineMarker,
  renameTimelineMarker,
} from '@strata/scene';
import { describe, expect, it } from 'vitest';

describe('motion presets and markers', () => {
  it('adds and removes timeline markers', () => {
    const doc = createDocument('test');
    const { doc: d1, id: tlId } = createTimeline(doc, 'Main', 3000);
    const d2 = addTimelineMarker(d1, tlId, { id: 'm1', name: 'Intro', progress: 0.25 });
    expect(d2.timelines?.[tlId]?.markers).toHaveLength(1);
  });

  it('creates and removes motion presets', () => {
    const doc = createDocument('test');
    const { doc: d1, id: tlId } = createTimeline(doc, 'Main', 3000);
    const { doc: d2, id: presetId } = createMotionPreset(d1, tlId, 'Fade In');
    expect(d2.motionPresets?.[presetId]?.timelineId).toBe(tlId);
    const d3 = removeMotionPreset(d2, presetId);
    expect(d3.motionPresets?.[presetId]).toBeUndefined();
  });

  it('renames a timeline marker', () => {
    const doc = createDocument('test');
    const { doc: d1, id: tlId } = createTimeline(doc, 'Main', 3000);
    const d2 = addTimelineMarker(d1, tlId, { id: 'm1', name: 'Intro', progress: 0.25 });
    const d3 = renameTimelineMarker(d2, tlId, 'm1', 'Outro');
    expect(d3.timelines?.[tlId]?.markers?.[0]?.name).toBe('Outro');
  });

  it('removes a timeline marker', () => {
    const doc = createDocument('test');
    const { doc: d1, id: tlId } = createTimeline(doc, 'Main', 3000);
    const d2 = addTimelineMarker(d1, tlId, { id: 'm1', name: 'Intro', progress: 0.25 });
    const d3 = removeTimelineMarker(d2, tlId, 'm1');
    expect(d3.timelines?.[tlId]?.markers).toHaveLength(0);
  });

  it('applyMotionPreset copies tracks onto target timeline', () => {
    const doc = createDocument('test');
    const { doc: d1, id: srcId } = createTimeline(doc, 'Source', 3000);
    const { doc: d2, id: tgtId } = createTimeline(d1, 'Target', 5000);
    const { doc: d3, trackId: trId } = addTrack(d2, srcId, 'node-1', 'opacity');
    const d4 = addKeyframe(d3, srcId, trId, { progress: 0, value: 0 });
    const d5 = addKeyframe(d4, srcId, trId, { progress: 1, value: 1 });
    const { doc: d6, id: presetId } = createMotionPreset(d5, srcId, 'Fade');
    const d7 = applyMotionPreset(d6, presetId, tgtId);
    const target = d7.timelines?.[tgtId];
    expect(target?.tracks).toHaveLength(1);
    expect(target?.tracks[0]?.property).toBe('opacity');
    expect(target?.tracks[0]?.keyframes).toHaveLength(2);
    expect(target?.tracks[0]?.id).not.toBe(trId);
  });
});
